from functools import reduce
from typing import List, Tuple


def trop_scalar_min(a: float, b: float, c: float) -> bool:
    """Lemma trop_scalar_min: a + min(b, c) == min(a + b, a + c)."""
    return a + min(b, c) == min(a + b, a + c)


def scalar_foldr_min(c: float, d: float, xs: List[float]) -> bool:
    """Theorem scalar_foldr_min over an arbitrary-length tropical sum."""
    lhs = c + reduce(lambda acc, x: min(x, acc), reversed(xs), d)
    rhs = reduce(lambda acc, x: min(x, acc), reversed([c + x for x in xs]), c + d)
    return lhs == rhs


if __name__ == "__main__":
    triples: List[Tuple[float, float, float]] = [(3, 7, 2), (-1, 5, 5), (10, -4, 8)]
    for a, b, c in triples:
        print(f"a+min(b,c)=min(a+b,a+c) for a={a},b={b},c={c}: {trop_scalar_min(a,b,c)}")
    print("scalar_foldr_min(5,100,[9,2,7,4]):", scalar_foldr_min(5, 100, [9, 2, 7, 4]))

from math import gcd, isqrt


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    for p in range(2, isqrt(n) + 1):
        if n % p == 0:
            return False
    return True


def fib_mod(n: int, m: int) -> int:
    a, b = 0 % m, 1 % m
    for _ in range(n):
        a, b = b, (a + b) % m
    return a


def pisano_period(m: int) -> int:
    a, b = 0, 1
    for p in range(1, 6 * m + 1):
        a, b = b, (a + b) % m
        if a == 0 and b == 1:
            return p
    raise RuntimeError("period not found")


if __name__ == "__main__":
    print("561 not prime:", not is_prime(561), " 17 prime:", is_prime(17))
    print("gcd(561,560):", gcd(561, 560))
    for p in (5, 7):
        print(f"x^{p} = x for all residues mod {p}:",
              all(pow(x, p, p) == x % p for x in range(p)))
    print("6 | n^3 - n on residues:", all((x**3 - x) % 6 == 0 for x in range(6)))
    for m in (2, 3, 5, 8, 10):
        p = pisano_period(m)
        ok = all(fib_mod(n + p, m) == fib_mod(n, m) for n in range(40))
        print(f"m={m}: Pisano period {p}, periodicity holds: {ok}")

